#!/usr/bin/env node

import { workflowText } from './yaml.mjs';   // r1.14 · W54 · M-F4: the workflow's own files, Windows line endings set aside
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readContracts } from './contracts.mjs';
import { QUALITY_GATES, GATES, decisionsFor, WAITS_ON_A_PERSON } from './gates.mjs';
import { STAGE_DIRS } from './run-files.mjs';
import { unquote } from './yaml.mjs';

export const OUT = '.github/OPERATING-A-RUN.md';
const SCRIPTS = '.github/registry/scripts.yaml';
const AGENTS = '.github/registry/agents.yaml';
const DOCS = 'specifications/documents.yaml';

export function scripts(file = SCRIPTS) {
  if (!existsSync(file)) return [];
  const text = workflowText(file).replace(/\r/g, '');
  return text.split(/^ {2}- path:[ \t]*/m).slice(1).map(block => {
    const key = k => { const m = new RegExp(`^ {4}${k}:[ \\t]*(.*)$`, 'm').exec(block); return m ? unquote(m[1].trim()) : null; };
    const stage = key('stage');
    return { path: block.split('\n')[0].trim(), disposition: key('disposition'), stage: stage ? Number(stage) : null,
             args: key('args') || null, purpose: key('purpose'), who: key('who'), reads: key('reads'), writes: key('writes') };
  });
}

function wrappers(file = AGENTS) {
  const out = { byAgent: new Map(), bySkill: new Map() };
  if (!existsSync(file)) return out;
  const text = workflowText(file);
  const start = text.indexOf('\nsubstrate_mapping:');
  if (start === -1) return out;
  for (const m of text.slice(start).matchAll(/^  - agent_file:\s*(\S+)\s*\n\s*design_agent:\s*(\S+)\s*\n(?:\s*covers:\s*\[([^\]]*)\]\s*\n)?/gm)) {
    if (!out.byAgent.has(m[2])) out.byAgent.set(m[2], m[1]);
    for (const skill of (m[3] || '').split(',').map(x => x.trim()).filter(Boolean))
      if (!out.bySkill.has(skill)) out.bySkill.set(skill, m[1]);
  }
  return out;
}

function perRun(file = DOCS) {
  if (!existsSync(file)) return new Map();
  const text = workflowText(file);
  const out = new Map();
  for (const m of text.matchAll(/^  - path:\s*"?(\{runs_root\}[^"\n]*)"?\s*\n\s*generator:\s*(\S+)\s*\n\s*guard:\s*(\S+)/gm)) {
    const stage = STAGE_DIRS.find(d => m[1].includes(`/${d}/`));
    const key = stage ? STAGE_DIRS.indexOf(stage) + 1 : 0;
    if (!out.has(key)) out.set(key, []);
    out.get(key).push({ path: m[1], generator: m[2], guard: m[3] });
  }
  return out;
}

export function render() {
  const c = readContracts();
  const wrap = wrappers();
  const gen = perRun();
  const reg = scripts();
  const operator = reg.filter(s => s.disposition === 'operator');
  const generators = reg.filter(s => s.disposition === 'generator');
  const L = [];

  L.push('# Operating a run');
  L.push('');
  L.push('**GENERATED by `.github/scripts/operator.mjs` from the workflow contracts, the gate model, the');
  L.push('scripts register and the run tree. Never edit it — `C144` fails when it drifts.** Regenerate with');
  L.push('`node .github/scripts/operator.mjs --write`.');
  L.push('');
  L.push('This page is for whoever operates a run by hand, which is not the person the workflow talks to.');
  L.push('The workflow makes these moves itself: agents write the documents and trigger the tasks, and the');
  L.push('tasks run the scripts. This page gives, as commands, the moves that take a run from one stage to');
  L.push('the next and the moves inside a stage that those depend on. The other tasks a person runs, such as');
  L.push('adding a problem in their own words, recording an edit or keeping a stale stage, are described in');
  L.push('`specifications/onboarding/TASKS.md`.');
  L.push('');
  L.push('**Substitute `{runs_root}` yourself.** Its one line is in `.github/runs-root`. Every command below');
  L.push('carries the placeholder for the same reason every skill contract does: the value differs per');
  L.push('recipient and a page generated against one of them would be wrong everywhere else.');
  L.push('');
  L.push('**`<run_id>` is the run identifier**, in the `{year}-{month}-{slug}` shape stage 1 assigns. The');
  L.push('run-state commands take the identifier; the check commands take the directory.');
  L.push('');
  L.push('---');
  L.push('');
  L.push('## Starting a run');
  L.push('');
  L.push('One command. It creates the whole tree — the ' + STAGE_DIRS.length + ' stage folders, their');
  L.push('`records/`, `read/`, the run record and a generated front page. **Nobody is ever asked to create a');
  L.push('folder**, and if one you were told to write into is missing, the run was not initialised.');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/run-state.mjs init <run_id>');
  L.push('```');
  L.push('');
  L.push('---');
  L.push('');
  L.push('## The seven stages');
  L.push('');
  L.push('**Every stage is the same five moves**: mark it running, let the agent produce, record what it');
  L.push('wrote, run the gate, record the gate. Stages with a decision gate add a person between the two.');
  L.push('');
  L.push('**Five stages also have a move inside the stage.**');
  L.push('');
  L.push('At stage 2, before the agent writes, the problem-material record is written from the files a person');
  L.push('put in `2-problems/supplied/`, without reading them; the agent is instructed to run this as a task.');
  L.push('Once the stage is produced, the driver writes each supplied file\'s measurement onto the items that');
  L.push('cite it, after the scripts listed under stage 2 below and before Q2. That list leaves the second out:');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/problem-material.mjs <run_id> --write');
  L.push('node .github/scripts/problem-material.mjs <run_id> --measure');
  L.push('```');
  L.push('');
  L.push('At stage 3, where a person put a market list in `3-competitive-analysis/supplied/`, the agent is');
  L.push('instructed to record it on the run before it works from that list:');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/market-material.mjs <run_id> --write');
  L.push('```');
  L.push('');
  L.push('Where the folder is empty there is nothing to record, and that command refuses. The agent searches if');
  L.push('VS Code\'s web search extension and a search key are installed, and otherwise works from web addresses');
  L.push('a person supplies.');
  L.push('');
  L.push('**Stage 4 takes its own route after the agent has written A8, and the `produced`, `G4` and `accepted`');
  L.push('lines under stage 4 below do not work for it.** Followed as written they accept the stage while A9,');
  L.push('the selected-solution document, is never written, and `C112` fails. A9 carries the reason for the');
  L.push('person\'s choice, and only the approval writes it. After marking stage 4 running and once A8 is written,');
  L.push('run these instead. The first records the stage as produced, runs the stage\'s scripts and Q4, and puts');
  L.push('the stage in review; the second records the person\'s choice; the third records G4 in their name,');
  L.push('writes A9 from the choice and accepts the stage:');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/advance.mjs <run_id>');
  L.push('node .github/scripts/run-state.mjs decide <run_id> 4 --kind choice --selection <solution id> --what "<why, in their words>" --by "<name>" --role <role>');
  L.push('node .github/scripts/advance.mjs <run_id> --approve --by "<name>" --role <role>');
  L.push('```');
  L.push('');

  L.push('At stage 5 a person chooses one MVP option while the stage is being written, before it is recorded as');
  L.push('produced, because the expansion is written for the option they chose. At stage 6 a person marks the');
  L.push('draft PRD agreed, and the agreed PRD is written from the draft word for word. Record each in the');
  L.push('person\'s name:');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/run-state.mjs decide <run_id> 5 --kind choice --selection <option id> --what "<why, in their words>" --by "<name>" --role <role>');
  L.push('node .github/scripts/run-state.mjs agree <run_id> 6 --by "<name>"');
  L.push('```');
  L.push('');

  for (const [gid, g] of Object.entries(QUALITY_GATES)) {
    const n = g.stage;
    const dir = STAGE_DIRS[n - 1];
    const gate = GATES[n] || {};
    const produces = [...(c.produces.get(n) || [])];
    const fromSkills = (c.skills.get(n) || []).map(sk => wrap.bySkill.get(sk)).filter(Boolean);
    const fromAgents = (c.agents.get(n) || []).map(a => wrap.byAgent.get(a) || a);
    const agents = [...new Set([...fromSkills, ...fromAgents])];
    const surfaces = gen.get(n) || [];
    const staged = reg.filter(s => s.stage === n);

    L.push(`### Stage ${n} — ${g.name}`);
    L.push('');
    L.push(`**Who:** ${agents.length ? agents.join(', ') : 'not declared by the contract'} · ` +
           `**Writes into:** \`{runs_root}/<run_id>/${dir}/\` · ` +
           `**Produces:** ${produces.length ? produces.join(', ') : 'nothing the contract names'}`);
    const owed = [...(c.requires.get(n) || [])];
    if (owed.length) L.push('');
    if (owed.length) L.push(`**Cannot be accepted until** the stages producing ${owed.join(', ')} are accepted. ` +
      '`run-state.mjs` refuses the move and `C143` catches a record written any other way.');
    L.push('');
    L.push('```bash');
    L.push(`node .github/scripts/run-state.mjs stage <run_id> ${n} running`);
    L.push('```');
    L.push('');
    L.push('Invoke the agent. When it says what it wrote, record it — one `--artifact` per artifact, and');
    L.push('one `--know-how` per body it read, at the version it read:');
    L.push('');
    const WHEN = { approval: 'approves', agreement: 'marks the draft agreed' };
    const byWorkflow = Object.entries(WAITS_ON_A_PERSON)
      .filter(([, w]) => w.writer === 'workflow' && Number(w.stage) === n && WHEN[w.after]).map(([id]) => id);
    L.push('```bash');
    L.push(`node .github/scripts/run-state.mjs stage <run_id> ${n} produced` +
           produces.filter(a => !byWorkflow.includes(a)).map(a => ` --artifact ${a}`).join('') +
           ' --know-how <body>@<version>');
    L.push('```');
    L.push('');
    for (const id of byWorkflow) {
      L.push(`${id} is written by the workflow when the person ${WHEN[WAITS_ON_A_PERSON[id].after]}; it is not recorded by hand.`);
      L.push('');
    }
    if (staged.length) {
      L.push('**This stage runs these before its gate.** The driver runs them once the stage is `produced`.');
      L.push('');
      L.push('```bash');
      for (const s of staged) L.push(`node ${s.path}${s.args ? ' ' + s.args : ''}   # ${s.purpose}`);
      L.push('```');
      L.push('');
    }
    if (surfaces.length) {
      L.push('**A generated document is registered to this stage.** Its generator writes it only where the run');
      L.push('holds what it is written from, and the check named beside it compares the copies the committed runs');
      L.push('hold with their generator. Write it with:');
      L.push('');
      L.push('```bash');
      for (const s of surfaces)
        L.push(`node ${s.generator} {runs_root}/<run_id> --write   # ${s.path.replace('{runs_root}/{run_id}/', '')}, guarded by ${s.guard}`);
      L.push('```');
      L.push('');
    }
    L.push(`Run the gate. **No agent runs its own gate** — the checker has to be independent of the producer:`);
    L.push('');
    L.push('```bash');
    L.push(`node .github/scripts/check.mjs {runs_root}/<run_id> --gate ${gate.quality || gid}`);
    L.push('```');
    L.push('');
    L.push('It returns `pass`, `fail` or `incomplete`, and `incomplete` is not a pass. **Add `--record` and');
    L.push('the verdict it computed is written for you**, through the same writer every other move goes');
    L.push('through — so what lands on the record is what the gate found rather than what you typed:');
    L.push('');
    L.push('```bash');
    L.push(`node .github/scripts/check.mjs {runs_root}/<run_id> --gate ${gate.quality || gid} --record --by "check.mjs, run independently of the producer"`);
    L.push('```');
    L.push('');
    L.push('An `incomplete` gate refuses to record: there is no verdict, and writing it as a fail would say');
    L.push('a check found something wrong. Recording by hand is still there when you need it:');
    L.push('');
    L.push('```bash');
    L.push(`node .github/scripts/run-state.mjs gate <run_id> ${n} ${gate.quality || gid} pass --by "check.mjs, run independently of the producer"`);
    L.push('```');
    L.push('');
    const takes = decisionsFor(n);
    if (takes.length) {
      L.push(takes.length === 1
        ? 'Now a person decides. Put the stage in front of them, and record the decision in their name:'
        : `Now a person decides **${takes.length} times** — ${takes.join(', then ')}. Each signature is its own ` +
          'command, because each is taken on its own day and the record carries the date it was taken:');
      L.push('');
      L.push('```bash');
      L.push(`node .github/scripts/run-state.mjs stage <run_id> ${n} in_review`);
      for (const id of takes)
        L.push(`node .github/scripts/run-state.mjs gate <run_id> ${n} ${id} pass --by "<the person's name>"`);
      L.push(`node .github/scripts/run-state.mjs stage <run_id> ${n} accepted`);
      L.push('```');
    } else {
      L.push(`**Stage ${n} has no decision gate**. ${gate.quality || gid} alone accepts it:`);
      L.push('');
      L.push('```bash');
      L.push(`node .github/scripts/run-state.mjs stage <run_id> ${n} accepted`);
      L.push('```');
    }
    L.push('');
    L.push('Then regenerate the front door, so the run says where it is:');
    L.push('');
    L.push('```bash');
    L.push('node .github/scripts/run-readme.mjs {runs_root}/<run_id> --write');
    L.push('```');
    L.push('');
  }

  L.push('---');
  L.push('');
  L.push('## When a gate fails');
  L.push('');
  L.push('**A stage that fails its quality gate does not reach a person.** It returns to the skill. The');
  L.push('writer moves the stage to `q_failed` on its own when you record a failing gate, and refuses');
  L.push('`accepted` from there. **The exception is a failure about a stage already accepted**, which the');
  L.push('skill cannot change from here: when every check that failed is about one, the person is asked to');
  L.push('sign it off, as below, unless one of those checks is one nobody can sign, or an earlier accepted stage\'s');
  L.push('sign-off over the same finding already carries to it, which the gate\'s closing names.');
  L.push('');
  L.push('**Unless a person signs what the run cannot satisfy.** `SPOCK: sign off a check this run cannot');
  L.push('meet` records the check or checks one gate run failed, on one stage, with one reason in the');
  L.push('signer\'s own words — `C11` alone, or `C11,C12,C171` where one cause failed several. **It may name');
  L.push('only what that gate recorded as failing**, and the writer refuses the rest. Where every check the gate');
  L.push('recorded as failing is signed, the stage stays `produced` and advances from there, and **the gate');
  L.push('result stays `fail` on the record, on the front page and in every report that reads them**, with the');
  L.push('signed exception recorded beside it. The checks that keep the record honest cannot be signed at all.');
  L.push('');
  L.push('**The signature works just as well after the stage has parked.** A stage sitting at `q_failed`');
  L.push('moves to `in_review` once every check its gate recorded as failing is signed, and it is the same');
  L.push('signature and the same task — nothing has to be undone first. **Do not send it back to `running`');
  L.push('to try again**: that edge is for work being rewritten, and it withdraws the signatures the stage');
  L.push('was carrying, which is how a run can park, be signed, and park again.');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/run-state.mjs gate <run_id> <stage> <Qn> fail --by "check.mjs, run independently of the producer"');
  L.push('```');
  L.push('');
  L.push('When a person sends a stage back rather than a check, record it in their name and role, with their reason.');
  L.push('It ends the stage\'s acceptance and its gate result, withdraws its decisions and the answers to its gate\'s questions');
  L.push('and keeps them on the record, and marks the later stages built');
  L.push('on it stale:');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/run-state.mjs retract <run_id> <stage> --by "<name>" --role "<role>" --reason "<why>"');
  L.push('```');
  L.push('');
  L.push('---');
  L.push('');
  L.push('## The whole run, and what it produced');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/check.mjs {runs_root}/<run_id>');
  L.push('```');
  L.push('');
  L.push('Every check the build implements, over the whole run. A run holding no artifact returns');
  L.push('`incomplete` and says so, because a gate cannot pass on a run that has produced nothing.');
  L.push('On a run started on build 1.12 or later, a document of an accepted stage edited with no edit recorded is');
  L.push('listed after the tally under *Reported, not a failure*, with the send-back and the edit task; it changes');
  L.push('neither the tally nor the exit code.');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/check.mjs {runs_root}/<run_id> --gates');
  L.push('```');
  L.push('');
  L.push('Which of the seven gates this build can run in full, and which half of each one ran.');
  L.push('');
  L.push('```bash');
  L.push('node .github/scripts/check.mjs {runs_root}/<run_id> --document A8');
  L.push('```');
  L.push('');
  L.push('**Everything the checks say about one document, and nothing about the rest of the run.** It is');
  L.push('the shortest loop this build has.');
  L.push('');
  L.push('---');
  L.push('');
  L.push('## Every command, and what it is for');
  L.push('');
  L.push('Generated from `.github/registry/scripts.yaml`. **What is not here is not yours to run**: the');
  L.push('rest of `.github/scripts/` is either a library nothing invokes directly or the harness this');
  L.push('repository proves itself with.');
  L.push('');
  L.push('| Command | What it is for |');
  L.push('|---|---|');
  for (const s of operator) L.push(`| \`node ${s.path}\` | ${s.purpose} |`);
  L.push('');
  L.push('**Generated surfaces.** Each writes a file something else reads, and each has a check that fails');
  L.push('when the file and the generator disagree. Never edit what they produce.');
  L.push('');
  L.push('| Command | What it writes |');
  L.push('|---|---|');
  for (const s of generators) L.push(`| \`node ${s.path}\` | ${s.purpose} |`);
  L.push('');
  return L.join('\n') + '\n';
}

if (process.argv[1] && resolve(fileURLToPath(import.meta.url)) === resolve(process.argv[1])) {
  const out = render();
  if (process.argv.includes('--write')) { writeFileSync(OUT, out); console.log(`wrote ${OUT}`); }
  else process.stdout.write(out);
}
